function article(input: Omit<Article, "publishedAt" | "featured" | "readMinutes">): Article {
  const prose = input.body.replace(/\[[^\]]*\]\([^)]*\)/g, (link) => link.slice(1, link.indexOf("]"))).replace(/[#*_>`]/g, " ");
  return {
    ...input,
    publishedAt: "2026-10-07T06:00:00.000Z",
    featured: false,
    readMinutes: Math.max(1, Math.ceil(prose.trim().split(/\s+/).length / 220)),
  };
}

